\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/8/14/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/8/\",\"title\":\"Chapter Eight: Attaining the Supreme\"}],\"url_path\":\"/en/library/bg/8/14/\",\"bb\":2162,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/8/13/\",\"title\":\"TEXT 13\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/8/15/\",\"title\":\"TEXT 15\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":2440,\"bb\":568193,\"url_path\":\"/en/library/bg/8/14/devanagari/\",\"body_final\":\"अनन्यचेता: सततं यो मां स्मरति नित्यश: ।
तस्याहं सुलभ: पार्थ नित्ययुक्तस्य योगिन: ॥ १४ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2441,\"bb\":2163,\"url_path\":\"/en/library/bg/8/14/b2163/\",\"body_value\":\"ananya-cetāḥ satataṁ
yo māṁ smarati nityaśaḥ
tasyāhaṁ su-labhaḥ pārtha
nitya-yuktasya yoginaḥ\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":2442,\"bb\":2164,\"url_path\":\"/en/library/bg/8/14/b2164/\",\"shadow_value\":\"ananya-cetāḥ – without deviation of the mind; satatam – always; yaḥ – anyone who; mām – Me (Kṛṣṇa); smarati – remembers; nityaśaḥ – regularly; tasya – to him; aham – I am; su-labhaḥ – very easy to achieve; pārtha – O son of Pṛthā; nitya – regularly; yuktasya – engaged; yoginaḥ – for the devotee.\",\"word_for_word_value\":[{\"word\":\"ananya-cetāḥ\",\"translation\":\"without deviation of the mind\"},{\"word\":\"satatam\",\"translation\":\"always\"},{\"word\":\"yaḥ\",\"translation\":\"anyone who\"},{\"word\":\"mām\",\"translation\":\"Me (Kṛṣṇa)\"},{\"word\":\"smarati\",\"translation\":\"remembers\"},{\"word\":\"nityaśaḥ\",\"translation\":\"regularly\"},{\"word\":\"tasya\",\"translation\":\"to him\"},{\"word\":\"aham\",\"translation\":\"I am\"},{\"word\":\"su-labhaḥ\",\"translation\":\"very easy to achieve\"},{\"word\":\"pārtha\",\"translation\":\"O son of Pṛthā\"},{\"word\":\"nitya\",\"translation\":\"regularly\"},{\"word\":\"yuktasya\",\"translation\":\"engaged\"},{\"word\":\"yoginaḥ\",\"translation\":\"for the devotee\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":2443,\"bb\":2165,\"url_path\":\"/en/library/bg/8/14/b2165/\",\"body_value\":\"For one who always remembers Me without deviation, I am easy to obtain, O son of Pṛthā, because of his constant engagement in devotional service.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2444,\"bb\":2166,\"url_path\":\"/en/library/bg/8/14/b2166/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2445,\"bb\":2167,\"url_path\":\"/en/library/bg/8/14/b2167/\",\"body_value\":\"$26\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2446,\"bb\":2168,\"url_path\":\"/en/library/bg/8/14/b2168/\",\"body_value\":\"The special qualification of the pure devotee is that he is always thinking of Kṛṣṇa without deviation and without considering the time or place. There should be no impediments. He should be able to carry out his service anywhere and at any time. Some say that the devotee should remain in holy places like Vṛndāvana or some holy town where the Lord lived, but a pure devotee can live anywhere and create the atmosphere of Vṛndāvana by his devotional service. It was Śrī Advaita who told Lord Caitanya, “Wherever You are, O Lord – there is Vṛndāvana.”\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2447,\"bb\":2169,\"url_path\":\"/en/library/bg/8/14/b2169/\",\"body_value\":\"$27\"}]}],\"short_title\":\"Bg. 8.14\",\"medium_title\":\"Bhagavad-gītā As It Is 8.14\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L28\",\"$L29\",\"$L2a\"]}]\n"])self.__next_f.push([1,"2c:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n32:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n28:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[